(() => {
  'use strict';
  const dayKey='ci-jing-week1-v3';
  const readCourse=()=>{try{return {...{day:0,done:[],status:{},week:1},...JSON.parse(localStorage.getItem(dayKey)||'{}')}}catch{return{day:0,done:[],status:{},week:1}}};
  const writeCourse=s=>localStorage.setItem(dayKey,JSON.stringify(s));
  const wordInfo=word=>{for(const d of (window.CiJingCourseData||[])){const item=(d.w||[]).find(x=>x[0]===word);if(item)return {meaning:item[1],collocation:item[2],example:item[3]};}return {meaning:'请回忆本词在上次学习中的核心义项。',collocation:'请回忆关联搭配。',example:''};};
  function tasks(){const words=window.CiJingVocabScheduler?.getDueTasks?.(6)||[];const collocation=window.CiJingCollocationScheduler?.getDueTasks?.(4)||[];return [...words.map(x=>({...x,kind:'word'})),...collocation.map(x=>({...x,kind:'collocation'}))].slice(0,6);}
  function makeGate(course){if(course.querySelector('#dueReviewGate'))return;const items=tasks();if(!items.length)return;const studio=course.querySelector('.studio');if(!studio)return;let index=0,finished=[];const gate=document.createElement('section');gate.id='dueReviewGate';gate.className='studio';gate.innerHTML='<div class="studio-top"><div><div class="studio-kicker">到期复习 · 优先完成</div><h3>先完成 '+items.length+' 项已到期内容</h3></div><div class="studio-count" id="dueReviewCount">1 / '+items.length+'</div></div><div id="dueReviewBody"></div>';studio.before(gate);studio.style.display='none';const rest=course.querySelector('#rest');if(rest)rest.style.display='none';
    const render=()=>{const item=items[index],info=item.kind==='word'?wordInfo(item.word):{meaning:'回忆固定搭配的中文义和缺失成分。',collocation:item.phrase,example:''};gate.querySelector('#dueReviewCount').textContent=(index+1)+' / '+items.length;gate.querySelector('#dueReviewBody').innerHTML='<div class="word-stage"><article class="focus-card"><div class="focus-word">'+(item.kind==='word'?item.word:item.phrase)+'</div><span class="pos">'+(item.kind==='word'?'词义与语境回忆':'固定搭配回忆')+'</span><div class="card-details"><div class="core-meaning">先在心里回忆，再核对</div></div></article><aside class="study-side"><div class="purpose">请写出这项内容的核心意思或补全结构；核对后再进入下一项。</div><label class="colloc-box"><b>我的回忆</b><input id="dueAnswer" placeholder="写出中文义、搭配或缺失部分"></label><div class="sentence-box"><b>核对：</b>'+info.meaning+'<br><b>搭配：</b>'+info.collocation+(info.example?'<br>'+info.example:'')+'</div></aside></div><div class="word-nav"><button id="dueAgain">想不起来 · 明天再练</button><button class="primary" id="dueGood">核对后，继续 →</button></div>';
      gate.querySelector('#dueAgain').onclick=()=>advance('again');gate.querySelector('#dueGood').onclick=()=>advance('good');};
    const advance=grade=>{const item=items[index];if(item.kind==='word')window.CiJingVocabScheduler?.recordCourseWord(item.word,grade);else window.CiJingCollocationScheduler?.record(item.phrase,grade);finished.push(item);index++;if(index<items.length){render();return;}gate.remove();studio.style.display='';if(rest)rest.style.display='';const s=readCourse();s.lastDueReview={at:new Date().toISOString(),count:finished.length};writeCourse(s);window.CiJingLearningRecord?.sync();};render();}
  const observer=new MutationObserver(()=>document.querySelectorAll('.word-course').forEach(makeGate));observer.observe(document.body,{childList:true,subtree:true});
  document.addEventListener('click',event=>{const save=event.target.closest('#saveReflection');if(!save)return;setTimeout(()=>{const s=readCourse();if(s.day>=5){s.week=(s.week||1)+1;s.day=0;s.done=[];s.status={};s.weekStartedAt=new Date().toISOString();writeCourse(s);window.CiJingLearningRecord?.sync();const result=document.getElementById('reflectDone');if(result)result.textContent='复盘已保存。第 '+s.week+' 周已生成：先完成到期复习，再开始新的学习内容。';}},0);},true);
})();
